import assert from 'node:assert/strict'
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import * as projen from 'projen'
import { Worktrunk } from 'projen-worktrunk'

const outdir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke-'))
const project = new projen.Project({ name: 'smoke', outdir })
const read = (file) => fs.readFileSync(path.join(outdir, file), 'utf8')

const worktrunk = new Worktrunk(project, {
  config: { 'pre-start': [{ install: 'pnpm install' }, { test: 'pnpm test' }] },
})
worktrunk.addCommand('pre-merge', 'check', 'pnpm check')

project.synth()

assert.ok(read('.config/wt.toml').includes('[[pre-start]]'))
assert.ok(read('.config/wt.toml').includes('pnpm check'))
assert.ok(read('.config/wt.toml').includes('Generated by projen'))
